      ],
      "paragraph_starts": [
        {"text": "Ces quelques denses pages du Carnet XI méritent une lecture attentive", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Sartre indique d'emblée le thème qui va guider sa réflexion", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Cette rencontre, Sartre avoue l'avoir lui-même parfois jugée « providentielle »", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Certes, depuis des siècles, ont eu lieu de telles rencontres philosophiques,", "continues_from_previous": false, "continues_to_next": true}
      ],
