        {"marker": "5", "context": "providentielle"},
        {"marker": "6", "context": "Que de temps j'ai gagné"},
        {"marker": "7", "context": "il venait à point"}
      ],
      "footnotes": [
        {"marker": "3", "text_start": "Les Carnets de la drôle de guerre comportent un assez grand nombre d'allusions"},
