        {"level": "running_header", "text": "LA BOMBE SARTRE", "position": "top"}
      ],
      "paragraph_starts": [
        {"text": "fait de sujets passifs recevant d'un seul coup un flot de", "continues_from_previous": true, "continues_to_next": false},
        {"text": "Malgré tout, Sartre sent qu'il risque d'aller trop loin en s'attribuant", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Ce témoignage inestimable et assurément sincère ne peut recevoir de l'historien", "continues_from_previous": false, "continues_to_next": false}
      ],
      "body_note_refs": [
        {"marker": "12", "context": "ignorer en 1940"},
